def compare_one(a, b):
    def parse_number(s):
        s = s.replace(',', '.')
        try:
            return float(s)
        except ValueError:
            return s

    def convert_to_float(x):
        if isinstance(x, str):
            return parse_number(x)
        return float(x)

    try:
        num_a = convert_to_float(a)
        num_b = convert_to_float(b)
    except (ValueError, TypeError):
        return None

    if num_a > num_b:
        return b if isinstance(b, str) else b
    elif num_b > num_a:
        return a if isinstance(a, str) else a
    else:
        return None
